local WinnowingMachineMaker = {}
local PRODUCTS = {
    simple_wood_winnowing = { name = "Preprosta lesena pihalna stroj", woodCost = 4, leatherCost = 1, time = 5, cost = 150, food = 22, happiness = 1, description = "Preprosta lesena pihalna stroj za čiščenje žita." },
    iron_vaned_winnowing = { name = "Železnolopatična pihalna stroj", woodCost = 4, ironCost = 2, leatherCost = 1, time = 8, cost = 380, food = 35, happiness = 2, prestige = 2, description = "Železnolopatična pihalna stroj za trgovce." },
    silver_geared_winnowing = { name = "Srebrnozobčana pihalna stroj", woodCost = 4, silverCost = 1, ironCost = 2, leatherCost = 1, time = 12, cost = 880, food = 50, happiness = 2, prestige = 6, description = "Srebrnozobčana pihalna stroj za plemiče." },
    gold_trimmed_winnowing = { name = "Zlatookrasna pihalna stroj", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 2, leatherCost = 1, time = 16, cost = 2000, food = 65, happiness = 3, prestige = 14, description = "Zlatookrasna pihalna stroj za visoke plemiče." },
    jewel_set_winnowing = { name = "Draguljasta pihalna stroj", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 2, leatherCost = 1, jewelCost = 1, time = 20, cost = 4400, food = 80, happiness = 5, prestige = 27, description = "Pihalna stroj z draguljem za visoko plemstvo." },
    royal_grand_winnowing = { name = "Kraljevski veliki pihalna stroj", woodCost = 6, goldCost = 2, silverCost = 2, ironCost = 2, leatherCost = 1, jewelCost = 2, pearlCost = 2, time = 27, cost = 9500, food = 95, happiness = 12, prestige = 58, description = "Velika kraljevska pihalna stroj z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    winnowing_workshop = { name = "Pihalna delavnica", cost = { gold = 290, wood = 160, stone = 140, iron = 6, leather = 4 }, upkeep = 6, qualityBonus = 5 },
    agricultural_loft = { name = "Kmetijska podstrešje", cost = { gold = 1050, wood = 320, stone = 280, silver = 6, iron = 6 }, upkeep = 24, qualityBonus = 18 },
    master_winnowing_atelier = { name = "Mojstrski pihalni atelje", cost = { gold = 2850, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 66, qualityBonus = 30 },
    royal_agriculture_palace = { name = "Kraljevska kmetijska palača", cost = { gold = 12200, wood = 600, stone = 800, gold = 78, jewel = 18 }, upkeep = 245, qualityBonus = 55, prestigeBonus = 50 },
}
WinnowingMachineMaker.woodStock = 20; WinnowingMachineMaker.ironStock = 12; WinnowingMachineMaker.leatherStock = 10; WinnowingMachineMaker.silverStock = 6; WinnowingMachineMaker.goldStock = 6; WinnowingMachineMaker.jewelStock = 4; WinnowingMachineMaker.pearlStock = 4
WinnowingMachineMaker.productStock = {}; WinnowingMachineMaker.buildings = {}; WinnowingMachineMaker.maker = nil; WinnowingMachineMaker.activeMaking = {}; WinnowingMachineMaker.totalProducts = 0; WinnowingMachineMaker.dayTimer = 0
function WinnowingMachineMaker.init() WinnowingMachineMaker.woodStock=20; WinnowingMachineMaker.ironStock=12; WinnowingMachineMaker.leatherStock=10; WinnowingMachineMaker.silverStock=6; WinnowingMachineMaker.goldStock=6; WinnowingMachineMaker.jewelStock=4; WinnowingMachineMaker.pearlStock=4; WinnowingMachineMaker.productStock={}; WinnowingMachineMaker.buildings={}; WinnowingMachineMaker.maker=nil; WinnowingMachineMaker.activeMaking={}; WinnowingMachineMaker.totalProducts=0; WinnowingMachineMaker.dayTimer=0; print("[WinnowingMachineMaker] Royal Winnowing Machine Maker System initialized (6 products, 4 buildings)") end
function WinnowingMachineMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WinnowingMachineMaker.maker={name=n or ("Pihalnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pihalnikar najet: %s (spretnost: %d)",WinnowingMachineMaker.maker.name,s),"success") end; return true end
function WinnowingMachineMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WinnowingMachineMaker.build(id) local ok,e=WinnowingMachineMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WinnowingMachineMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WinnowingMachineMaker.getQualityBonus() local b=0; for _,bd in ipairs(WinnowingMachineMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WinnowingMachineMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and WinnowingMachineMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and WinnowingMachineMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.leatherCost and WinnowingMachineMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and WinnowingMachineMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WinnowingMachineMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WinnowingMachineMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WinnowingMachineMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WinnowingMachineMaker.buildings==0 then return false,"Potrebna pihalna delavnica" end; if not WinnowingMachineMaker.maker then return false,"Potreben pihalnikar" end; return true end
function WinnowingMachineMaker.make(pt,qty) qty=qty or 1; local ok,e=WinnowingMachineMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then WinnowingMachineMaker.woodStock=WinnowingMachineMaker.woodStock-d.woodCost*qty end; if d.ironCost then WinnowingMachineMaker.ironStock=WinnowingMachineMaker.ironStock-d.ironCost*qty end; if d.leatherCost then WinnowingMachineMaker.leatherStock=WinnowingMachineMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then WinnowingMachineMaker.silverStock=WinnowingMachineMaker.silverStock-d.silverCost*qty end; if d.goldCost then WinnowingMachineMaker.goldStock=WinnowingMachineMaker.goldStock-d.goldCost*qty end; if d.jewelCost then WinnowingMachineMaker.jewelStock=WinnowingMachineMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then WinnowingMachineMaker.pearlStock=WinnowingMachineMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if WinnowingMachineMaker.maker then t=math.max(1,t-math.floor(WinnowingMachineMaker.maker.skill/13)) end; table.insert(WinnowingMachineMaker.activeMaking,{id="winnowing_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WinnowingMachineMaker.completeMaking(m) local q=1.0+(WinnowingMachineMaker.getQualityBonus()/100); if WinnowingMachineMaker.maker then q=q+(WinnowingMachineMaker.maker.skill/140) end; q=math.min(2.5,q); WinnowingMachineMaker.productStock[m.productType]=(WinnowingMachineMaker.productStock[m.productType] or 0)+m.quantity; WinnowingMachineMaker.totalProducts=WinnowingMachineMaker.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WinnowingMachineMaker.maker then WinnowingMachineMaker.maker.itemsMade=WinnowingMachineMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then WinnowingMachineMaker.maker.skill=math.min(100,WinnowingMachineMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pihalna stroj izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"winnowing.completed",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function WinnowingMachineMaker.update(dt) if not _G.state then return end; WinnowingMachineMaker.dayTimer=WinnowingMachineMaker.dayTimer+dt; if WinnowingMachineMaker.dayTimer>=30 then WinnowingMachineMaker.dayTimer=0; for i=#WinnowingMachineMaker.activeMaking,1,-1 do local m=WinnowingMachineMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WinnowingMachineMaker.completeMaking(m); table.remove(WinnowingMachineMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WinnowingMachineMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WinnowingMachineMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WinnowingMachineMaker.getStats() return {woodStock=WinnowingMachineMaker.woodStock,ironStock=WinnowingMachineMaker.ironStock,leatherStock=WinnowingMachineMaker.leatherStock,silverStock=WinnowingMachineMaker.silverStock,goldStock=WinnowingMachineMaker.goldStock,jewelStock=WinnowingMachineMaker.jewelStock,pearlStock=WinnowingMachineMaker.pearlStock,productStock=WinnowingMachineMaker.productStock,numBuildings=#WinnowingMachineMaker.buildings,hasMaker=WinnowingMachineMaker.maker~=nil,makerName=WinnowingMachineMaker.maker and WinnowingMachineMaker.maker.name or "—",makerSkill=WinnowingMachineMaker.maker and WinnowingMachineMaker.maker.skill or 0,activeMaking=#WinnowingMachineMaker.activeMaking,totalProducts=WinnowingMachineMaker.totalProducts} end
return WinnowingMachineMaker
